insert into public.leagues (id, code, name, roman, color_hex, emblem, description) values
  (1, 'bronze', 'Brąz', 'I', '#CD7F32', 'shield.lefthalf.filled', 'Początek drogi. Tu uczysz się zasad i zbierasz pierwsze LP. Z Brązu nie można spaść.'),
  (2, 'silver', 'Srebro', 'II', '#C0C7D1', 'shield.fill', 'Gracze, którzy regularnie wracają do quizów. Rywalizacja nabiera tempa.'),
  (3, 'gold', 'Złoto', 'III', '#F5C542', 'crown.fill', 'Elita regularnych graczy. Każdy tydzień to walka o miejsce w pierwszej dziesiątce.'),
  (4, 'platinum', 'Platyna', 'IV', '#7FE7F2', 'diamond.fill', 'Mistrzowie wiedzy z wielu dziedzin. Jeden słabszy tydzień może kosztować spadek.'),
  (5, 'legend', 'Legenda', 'V', '#B57BFF', 'sparkles', 'Szczyt QuizVerse. Najwyższa liga – miejsca awansowe oznaczają utrzymanie tytułu Legendy.')
