insert into public.knowledge_articles (id, slug, category_id, subcategory_id, title, summary, body, key_facts, dates, terms, related_slugs, sources) overriding system value values
  (1, 'chrzest-polski', 1, 103, 'Chrzest Polski (966)', 'Przyjęcie chrześcijaństwa przez Mieszka I włączyło państwo Polan w krąg kultury łacińskiej.', 'W 966 roku książę Mieszko I przyjął chrzest, najprawdopodobniej w Wielką Sobotę 14 kwietnia. Decyzja była związana z małżeństwem z czeską księżniczką Dobrawą (965) i miała ogromne znaczenie polityczne: wzmacniała pozycję państwa wobec sąsiadów, w tym Cesarstwa, oraz otwierała drogę do budowy organizacji kościelnej. W 968 r. powstało biskupstwo misyjne w Poznaniu z biskupem Jordanem.', '["Mieszko I – pierwszy historyczny władca Polski", "Żona: Dobrawa Przemyślidka", "968 – biskupstwo w Poznaniu"]'::jsonb, '[{"date": "965", "label": "Ślub Mieszka I z Dobrawą"}, {"date": "966", "label": "Chrzest Mieszka I"}, {"date": "1000", "label": "Zjazd gnieźnieński"}]'::jsonb, '[{"term": "Chrystianizacja", "definition": "Proces przyjmowania chrześcijaństwa przez społeczność."}]'::jsonb, array['zjazd-gnieznienski','grunwald-1410']::text[], '[{"title": "Encyklopedia PWN – chrzest Polski", "url": "https://encyklopedia.pwn.pl/"}]'::jsonb),
  (2, 'grunwald-1410', 1, 102, 'Bitwa pod Grunwaldem (1410)', 'Jedna z największych bitew średniowiecznej Europy – zwycięstwo Polski i Litwy nad zakonem krzyżackim.', '15 lipca 1410 roku wojska Królestwa Polskiego pod wodzą Władysława II Jagiełły oraz Wielkiego Księstwa Litewskiego dowodzone przez Witolda pokonały armię zakonu krzyżackiego. Zginął wielki mistrz Ulrich von Jungingen. Mimo zwycięstwa nie zdobyto Malborka, a I pokój toruński (1411) przyniósł umiarkowane korzyści.', '["Dowódcy: Władysław Jagiełło, wielki książę Witold", "Poległ wielki mistrz Ulrich von Jungingen", "Wielka wojna 1409–1411"]'::jsonb, '[{"date": "15.07.1410", "label": "Bitwa"}, {"date": "1411", "label": "I pokój toruński"}]'::jsonb, '[{"term": "Zakon krzyżacki", "definition": "Zakon rycerski Najświętszej Marii Panny, władający państwem w Prusach."}]'::jsonb, array['chrzest-polski']::text[], '[{"title": "Jan Długosz, Roczniki", "url": "https://pl.wikisource.org/"}]'::jsonb),
  (3, 'ii-wojna-swiatowa', 1, 107, 'II wojna światowa', 'Najbardziej krwawy konflikt w dziejach ludzkości (1939–1945).', 'Wojna rozpoczęła się 1 września 1939 r. atakiem Niemiec na Polskę; 17 września do inwazji dołączył ZSRR. Konflikt objął Europę, Afrykę, Azję i Pacyfik. W Europie zakończył się bezwarunkową kapitulacją Niemiec 8 maja 1945 r., a na świecie kapitulacją Japonii podpisaną 2 września 1945 r.', '["Ok. 70–85 mln ofiar", "Holokaust – ludobójstwo Żydów", "Powstanie ONZ w 1945 r."]'::jsonb, '[{"date": "1.09.1939", "label": "Atak Niemiec na Polskę"}, {"date": "17.09.1939", "label": "Agresja ZSRR"}, {"date": "6.06.1944", "label": "Lądowanie w Normandii"}, {"date": "8.05.1945", "label": "Kapitulacja Niemiec"}, {"date": "2.09.1945", "label": "Kapitulacja Japonii"}]'::jsonb, '[{"term": "Blitzkrieg", "definition": "Wojna błyskawiczna – szybkie uderzenia wojsk pancernych i lotnictwa."}]'::jsonb, array['enigma']::text[], '[{"title": "Encyklopedia PWN – II wojna światowa", "url": "https://encyklopedia.pwn.pl/"}]'::jsonb),
  (4, 'enigma', 1, 107, 'Złamanie Enigmy', 'Polscy matematycy jako pierwsi złamali szyfr niemieckiej maszyny Enigma.', 'W grudniu 1932 r. Marian Rejewski, wykorzystując teorię permutacji, odtworzył okablowanie wirników wojskowej Enigmy. Wraz z Jerzym Różyckim i Henrykiem Zygalskim stworzył metody i urządzenia (cyklometr, bomba kryptologiczna, płachty Zygalskiego). W lipcu 1939 r. Polacy przekazali swoje osiągnięcia Francuzom i Brytyjczykom, co pomogło w pracach w Bletchley Park.', '["Marian Rejewski, Jerzy Różycki, Henryk Zygalski", "Biuro Szyfrów w Warszawie", "Bletchley Park – kontynuacja prac (m.in. Alan Turing)"]'::jsonb, '[{"date": "1932", "label": "Złamanie szyfru"}, {"date": "lipiec 1939", "label": "Przekazanie wiedzy aliantom"}]'::jsonb, '[{"term": "Kryptoanaliza", "definition": "Łamanie szyfrów bez znajomości klucza."}]'::jsonb, array['ii-wojna-swiatowa','alan-turing']::text[], '[{"title": "Muzeum Historii Polski", "url": "https://muzhp.pl/"}]'::jsonb),
  (5, 'fotosynteza', 6, 601, 'Fotosynteza', 'Proces, w którym rośliny zamieniają energię światła w energię chemiczną.', 'Fotosynteza zachodzi w chloroplastach dzięki chlorofilowi. Z dwutlenku węgla i wody, przy udziale światła, powstaje glukoza i tlen: 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂. Składa się z fazy zależnej od światła (w tylakoidach) i fazy niezależnej – cyklu Calvina (w stromie).', '["Organellum: chloroplast", "Barwnik: chlorofil", "Produkt uboczny: tlen"]'::jsonb, '[]'::jsonb, '[{"term": "Cykl Calvina", "definition": "Ciąg reakcji wiążących CO₂ w cukry."}]'::jsonb, array['mitochondrium']::text[], '[{"title": "Biologia na czasie (podręcznik)", "url": "https://www.nowaera.pl/"}]'::jsonb),
  (6, 'mitochondrium', 6, 601, 'Mitochondrium', '„Elektrownia komórki” – miejsce oddychania komórkowego i produkcji ATP.', 'Mitochondria wytwarzają większość ATP w procesie oddychania tlenowego. Mają własne DNA i rybosomy, co wspiera teorię endosymbiozy – pochodzą od dawnych bakterii wchłoniętych przez komórkę.', '["Produkują ATP", "Mają własne DNA", "Teoria endosymbiozy"]'::jsonb, '[]'::jsonb, '[{"term": "ATP", "definition": "Adenozynotrifosforan – nośnik energii w komórce."}]'::jsonb, array['fotosynteza']::text[], '[{"title": "Encyklopedia PWN – mitochondria", "url": "https://encyklopedia.pwn.pl/"}]'::jsonb),
  (7, 'uklad-sloneczny', 24, 2401, 'Układ Słoneczny', 'Słońce i krążące wokół niego planety, planety karłowate, księżyce i małe ciała.', 'Układ Słoneczny powstał ok. 4,6 mld lat temu. Ma osiem planet: Merkury, Wenus, Ziemię i Marsa (skaliste) oraz Jowisza, Saturna, Urana i Neptuna (olbrzymy). Pluton od 2006 r. jest klasyfikowany jako planeta karłowata. Największą planetą jest Jowisz, a najgorętszą – Wenus.', '["8 planet", "Wiek ok. 4,6 mld lat", "Pluton – planeta karłowata od 2006 r."]'::jsonb, '[{"date": "2006", "label": "Nowa definicja planety (IAU)"}]'::jsonb, '[{"term": "Jednostka astronomiczna", "definition": "Średnia odległość Ziemia–Słońce, ok. 150 mln km."}]'::jsonb, array['kopernik']::text[], '[{"title": "NASA Solar System Exploration", "url": "https://science.nasa.gov/solar-system/"}]'::jsonb),
  (8, 'kopernik', 24, 2401, 'Mikołaj Kopernik i heliocentryzm', 'Kopernik umieścił Słońce w centrum układu planetarnego.', 'Mikołaj Kopernik (1473–1543), urodzony w Toruniu, w dziele „De revolutionibus orbium coelestium” (1543) przedstawił model heliocentryczny. Zapoczątkował tym rewolucję naukową kontynuowaną przez Keplera, Galileusza i Newtona.', '["Urodzony w Toruniu (1473)", "Dzieło: „O obrotach sfer niebieskich” (1543)", "Był też lekarzem, ekonomistą i administratorem"]'::jsonb, '[{"date": "1473", "label": "Narodziny"}, {"date": "1543", "label": "Wydanie dzieła i śmierć"}]'::jsonb, '[{"term": "Heliocentryzm", "definition": "Model, w którym Słońce jest w centrum, a planety krążą wokół niego."}]'::jsonb, array['uklad-sloneczny']::text[], '[{"title": "Encyklopedia PWN – Kopernik", "url": "https://encyklopedia.pwn.pl/"}]'::jsonb),
  (9, 'uklad-okresowy', 8, 801, 'Układ okresowy pierwiastków', 'Tablica porządkująca pierwiastki według liczby atomowej.', 'Dmitrij Mendelejew w 1869 r. ułożył pierwiastki według mas atomowych i właściwości, zostawiając luki na nieodkryte pierwiastki. Współczesny układ porządkuje pierwiastki wg liczby atomowej (liczby protonów) i liczy 118 pierwiastków w 7 okresach i 18 grupach.', '["118 pierwiastków", "18 grup, 7 okresów", "Najlżejszy: wodór"]'::jsonb, '[{"date": "1869", "label": "Tablica Mendelejewa"}]'::jsonb, '[{"term": "Liczba atomowa", "definition": "Liczba protonów w jądrze atomu."}]'::jsonb, array['sklodowska-curie']::text[], '[{"title": "IUPAC Periodic Table", "url": "https://iupac.org/what-we-do/periodic-table-of-elements/"}]'::jsonb),
  (10, 'sklodowska-curie', 8, 801, 'Maria Skłodowska-Curie', 'Odkrywczyni polonu i radu, dwukrotna noblistka.', 'Urodzona w Warszawie w 1867 r. Wraz z Piotrem Curie odkryła polon (nazwany na cześć Polski) i rad (1898). Nobel z fizyki (1903, wspólnie z Piotrem Curie i Henrim Becquerelem) oraz z chemii (1911). Pierwsza kobieta profesor Sorbony.', '["Nobel z fizyki 1903 i chemii 1911", "Odkrycie polonu i radu", "Pierwsza kobieta – profesor Sorbony"]'::jsonb, '[{"date": "1867", "label": "Narodziny w Warszawie"}, {"date": "1898", "label": "Odkrycie polonu i radu"}]'::jsonb, '[{"term": "Promieniotwórczość", "definition": "Samorzutny rozpad jąder atomowych z emisją promieniowania."}]'::jsonb, array['uklad-okresowy']::text[], '[{"title": "The Nobel Prize – Marie Curie", "url": "https://www.nobelprize.org/"}]'::jsonb),
  (11, 'konstytucja-rp', 3, 301, 'Konstytucja RP z 1997 r.', 'Najwyższy akt prawny Rzeczypospolitej Polskiej.', 'Konstytucja została uchwalona przez Zgromadzenie Narodowe 2 kwietnia 1997 r., przyjęta w referendum 25 maja 1997 r. i weszła w życie 17 października 1997 r. Składa się z preambuły i 13 rozdziałów (243 artykuły). Ustanawia trójpodział władzy: ustawodawczą (Sejm i Senat), wykonawczą (Prezydent i Rada Ministrów) i sądowniczą (sądy i trybunały).', '["243 artykuły, 13 rozdziałów", "Trójpodział władzy", "Kadencja Sejmu: 4 lata; Prezydenta: 5 lat"]'::jsonb, '[{"date": "2.04.1997", "label": "Uchwalenie"}, {"date": "17.10.1997", "label": "Wejście w życie"}]'::jsonb, '[{"term": "Trójpodział władzy", "definition": "Koncepcja Monteskiusza: rozdział władzy ustawodawczej, wykonawczej i sądowniczej."}]'::jsonb, array['konstytucja-3-maja']::text[], '[{"title": "Sejm RP – Konstytucja", "url": "https://www.sejm.gov.pl/prawo/konst/polski/kon1.htm"}]'::jsonb),
  (12, 'konstytucja-3-maja', 3, 301, 'Konstytucja 3 Maja', 'Ustawa Rządowa z 1791 r. – pierwsza w Europie i druga na świecie nowoczesna konstytucja.', 'Uchwalona 3 maja 1791 r. przez Sejm Czteroletni. Wprowadzała trójpodział władzy, znosiła liberum veto i wolną elekcję (tron dziedziczny). Obowiązywała krótko – jej obalenie przyniosła konfederacja targowicka i wojna z Rosją 1792 r.', '["Sejm Czteroletni (1788–1792)", "Zniesienie liberum veto", "Druga na świecie po konstytucji USA (1787)"]'::jsonb, '[{"date": "3.05.1791", "label": "Uchwalenie"}, {"date": "1792", "label": "Wojna w obronie konstytucji"}]'::jsonb, '[{"term": "Liberum veto", "definition": "Zasada, wg której sprzeciw jednego posła zrywał sejm."}]'::jsonb, array['konstytucja-rp']::text[], '[{"title": "Muzeum Historii Polski", "url": "https://muzhp.pl/"}]'::jsonb),
  (13, 'twierdzenie-pitagorasa', 5, 502, 'Twierdzenie Pitagorasa', 'W trójkącie prostokątnym suma kwadratów przyprostokątnych równa się kwadratowi przeciwprostokątnej.', 'Jeśli a i b są przyprostokątnymi, a c przeciwprostokątną, to a² + b² = c². Klasyczny przykład to trójkąt 3–4–5. Twierdzenie znano w Babilonii, a jego dowód przypisuje się szkole pitagorejskiej.', '["a² + b² = c²", "Trójka pitagorejska: 3, 4, 5", "Twierdzenie odwrotne też jest prawdziwe"]'::jsonb, '[]'::jsonb, '[{"term": "Przeciwprostokątna", "definition": "Najdłuższy bok trójkąta prostokątnego, naprzeciw kąta prostego."}]'::jsonb, array[]::text[], '[{"title": "Matematyka – Encyklopedia PWN", "url": "https://encyklopedia.pwn.pl/"}]'::jsonb),
  (14, 'pan-tadeusz', 9, 901, '„Pan Tadeusz”', 'Epopeja narodowa Adama Mickiewicza (1834).', 'Pełny tytuł: „Pan Tadeusz, czyli Ostatni zajazd na Litwie. Historia szlachecka z roku 1811 i 1812 we dwunastu księgach wierszem”. Napisany na emigracji w Paryżu, wydany w 1834 r. Rozpoczyna się Inwokacją „Litwo! Ojczyzno moja!”.', '["Autor: Adam Mickiewicz", "12 ksiąg, trzynastozgłoskowiec", "Akcja: Soplicowo, 1811–1812"]'::jsonb, '[{"date": "1834", "label": "Wydanie w Paryżu"}]'::jsonb, '[{"term": "Epopeja", "definition": "Obszerny utwór epicki ukazujący losy społeczności na tle przełomowych wydarzeń."}]'::jsonb, array[]::text[], '[{"title": "Wolne Lektury – Pan Tadeusz", "url": "https://wolnelektury.pl/katalog/lektura/pan-tadeusz/"}]'::jsonb),
  (15, 'alan-turing', 20, 2004, 'Alan Turing', 'Brytyjski matematyk, ojciec teoretycznej informatyki.', 'W 1936 r. Turing opisał abstrakcyjną maszynę (maszynę Turinga), która formalizuje pojęcie obliczalności. Podczas II wojny światowej pracował w Bletchley Park nad łamaniem Enigmy, rozwijając wcześniejsze osiągnięcia polskich kryptologów. Zaproponował też test Turinga dotyczący sztucznej inteligencji (1950).', '["Maszyna Turinga (1936)", "Bletchley Park", "Test Turinga (1950)"]'::jsonb, '[{"date": "1936", "label": "„On Computable Numbers”"}, {"date": "1950", "label": "„Computing Machinery and Intelligence”"}]'::jsonb, '[{"term": "Obliczalność", "definition": "Własność problemu, który można rozwiązać algorytmem."}]'::jsonb, array['enigma']::text[], '[{"title": "Encyclopaedia Britannica – Alan Turing", "url": "https://www.britannica.com/biography/Alan-Turing"}]'::jsonb),
  (16, 'mitologia-grecka', 13, 1301, 'Bogowie olimpijscy', 'Dwunastu najważniejszych bogów greckich mieszkających na Olimpie.', 'Władcą Olimpu był Zeus, bóg nieba i piorunów. Jego bracia to Posejdon (morza) i Hades (podziemia, choć nie zaliczany do dwunastu olimpijczyków). Hera była żoną Zeusa i opiekunką małżeństwa, Atena – boginią mądrości i wojny sprawiedliwej, Apollo – bogiem sztuki i światła, Hermes – posłańcem bogów.', '["Zeus – władca bogów", "Atena narodziła się z głowy Zeusa", "Rzymskie odpowiedniki: Jowisz, Junona, Minerwa…"]'::jsonb, '[]'::jsonb, '[{"term": "Panteon", "definition": "Ogół bóstw danej religii."}]'::jsonb, array[]::text[], '[{"title": "Jan Parandowski, Mitologia", "url": "https://wolnelektury.pl/"}]'::jsonb),
  (17, 'igrzyska-olimpijskie', 18, 1801, 'Igrzyska olimpijskie', 'Od starożytnej Olimpii do nowożytnych igrzysk Pierre’a de Coubertina.', 'Starożytne igrzyska odbywały się w Olimpii od 776 p.n.e. Nowożytne igrzyska wskrzesił Pierre de Coubertin – pierwsze odbyły się w Atenach w 1896 r. Pięć kół olimpijskich symbolizuje pięć zamieszkanych kontynentów. Zimowe igrzyska rozgrywane są od 1924 r.', '["776 p.n.e. – pierwsze igrzyska w Olimpii", "1896 – Ateny, pierwsze nowożytne", "1924 – pierwsze zimowe (Chamonix)"]'::jsonb, '[{"date": "776 p.n.e.", "label": "Starożytne igrzyska"}, {"date": "1896", "label": "Ateny"}]'::jsonb, '[{"term": "Znicz olimpijski", "definition": "Ogień zapalany w Olimpii i przenoszony do miasta-gospodarza."}]'::jsonb, array[]::text[], '[{"title": "Olympics.com", "url": "https://olympics.com/"}]'::jsonb),
  (18, 'inflacja', 21, 2102, 'Inflacja', 'Wzrost ogólnego poziomu cen, czyli spadek siły nabywczej pieniądza.', 'Inflację mierzy się najczęściej wskaźnikiem cen towarów i usług konsumpcyjnych (CPI). Bank centralny – w Polsce Narodowy Bank Polski – stara się utrzymać inflację blisko celu (2,5% ± 1 pkt proc.), m.in. zmieniając stopy procentowe.', '["Miara: CPI", "Cel NBP: 2,5% ± 1 pkt proc.", "Narzędzie: stopy procentowe"]'::jsonb, '[]'::jsonb, '[{"term": "Deflacja", "definition": "Spadek ogólnego poziomu cen."}]'::jsonb, array[]::text[], '[{"title": "NBP – edukacja ekonomiczna", "url": "https://www.nbp.pl/"}]'::jsonb),
  (19, 'everest', 2, 206, 'Mount Everest', 'Najwyższy szczyt Ziemi w Himalajach, na granicy Nepalu i Chin.', 'Wysokość 8848,86 m n.p.m. ustalono wspólnie przez Nepal i Chiny w 2020 r. Pierwsze potwierdzone wejście: Edmund Hillary i Tenzing Norgay, 29 maja 1953 r. Pierwsza Polka na szczycie – Wanda Rutkiewicz (1978).', '["8848,86 m n.p.m.", "1953 – Hillary i Tenzing", "Pierwsze zimowe wejście: Polacy (Wielicki, Cichy, 1980)"]'::jsonb, '[{"date": "1953", "label": "Pierwsze wejście"}, {"date": "17.02.1980", "label": "Pierwsze zimowe wejście"}]'::jsonb, '[{"term": "Ośmiotysięcznik", "definition": "Szczyt powyżej 8000 m n.p.m.; jest ich 14."}]'::jsonb, array[]::text[], '[{"title": "National Geographic – Everest", "url": "https://www.nationalgeographic.com/"}]'::jsonb),
  (20, 'chopin', 15, 1504, 'Fryderyk Chopin', 'Najwybitniejszy polski kompozytor romantyzmu.', 'Urodzony w 1810 r. w Żelazowej Woli, zmarł w 1849 r. w Paryżu. Pisał niemal wyłącznie na fortepian: mazurki, polonezy, nokturny, etiudy, ballady, dwa koncerty fortepianowe. Jego serce spoczywa w kościele Świętego Krzyża w Warszawie. Od 1927 r. odbywa się Międzynarodowy Konkurs Pianistyczny im. Chopina.', '["Żelazowa Wola, 1810", "Serce w kościele św. Krzyża", "Konkurs chopinowski co 5 lat"]'::jsonb, '[{"date": "1810", "label": "Narodziny"}, {"date": "1849", "label": "Śmierć w Paryżu"}]'::jsonb, '[{"term": "Mazurek", "definition": "Polski taniec ludowy w metrum trójdzielnym."}]'::jsonb, array[]::text[], '[{"title": "Narodowy Instytut Fryderyka Chopina", "url": "https://nifc.pl/"}]'::jsonb)
