insert into public.questions (id, category_id, subcategory_id, difficulty, kind, prompt, clues, explanation, article_id, source, sources, status, content_hash) values
  ('236f99f7-3573-52a0-bc82-bf3760323857', 1, 103, 1, 'standard', 'W którym roku Mieszko I przyjął chrzest?', null, 'Chrzest Mieszka I w 966 r. uznaje się za symboliczny początek państwa polskiego.', 1, 'manual', '[{"title": "Encyklopedia PWN – chrzest Polski", "url": "https://encyklopedia.pwn.pl/"}]'::jsonb, 'approved', 'd4f83a615c4c20ec82e473ba6c1cbcad'),
  ('660a2180-a7f8-5d32-85e7-8ea21eaed811', 1, 103, 2, 'standard', 'Kto był pierwszym koronowanym królem Polski?', null, 'Bolesław Chrobry koronował się w 1025 r., niedługo przed śmiercią.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '467b4cab35aabe4ecdaad3f4c0becca0'),
  ('31d3c69e-bbc6-58dc-ab8f-abcd65da689b', 1, 103, 2, 'standard', 'Którego dnia wybuchło Powstanie Warszawskie?', null, 'Powstanie wybuchło 1 sierpnia 1944 r. o godzinie „W” (17:00) i trwało 63 dni.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'f3f02f4bf1d62af589985dcdb148c955'),
  ('e605b532-bcf8-5dd3-8a37-6d2ad75510ae', 1, 103, 3, 'standard', 'W którym roku zawarto unię lubelską?', null, 'Unia lubelska (1569) przekształciła unię personalną Polski i Litwy w realną – powstała Rzeczpospolita Obojga Narodów.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'c4fd653316d3c3d6294162580e98077c'),
  ('f308b02a-e915-5977-9017-74c16512fcba', 1, 103, 3, 'standard', 'Który władca założył Akademię Krakowską w 1364 roku?', null, 'Kazimierz III Wielki ufundował Akademię Krakowską (dziś Uniwersytet Jagielloński) w 1364 r.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '0b863085e01073f708aed5c47d0bf24b'),
  ('4f91b8e3-0720-5f7b-b1b1-fbd1b663ea9b', 1, 103, 4, 'standard', 'Który akt z 1138 roku zapoczątkował rozbicie dzielnicowe w Polsce?', null, 'Testament Bolesława Krzywoustego podzielił kraj między synów i wprowadził zasadę senioratu.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '7f709767e7a2525cd9b15b25dee1b0f2'),
  ('45323ea6-44d7-54f6-86a3-8d49ae880e87', 1, 103, 5, 'standard', 'Który z wymienionych był współzałożycielem Komitetu Obrony Robotników (1976)?', null, 'KOR założyli m.in. Jacek Kuroń, Antoni Macierewicz, Jan Józef Lipski i Jerzy Andrzejewski; Wałęsa był liderem Solidarności, nie KOR.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '33147d1862e25d6487f56f3a5a0b144a'),
  ('1db3d09e-736b-527e-b013-2d922364728f', 1, 102, 2, 'standard', 'Kiedy rozegrała się bitwa pod Grunwaldem?', null, 'Bitwa pod Grunwaldem odbyła się 15 lipca 1410 r.', 2, 'manual', '[{"title": "Jan Długosz, Roczniki", "url": "https://pl.wikisource.org/"}]'::jsonb, 'approved', '8a5faed656554dd22555366900f00336'),
  ('761fba23-52bd-54a5-ba22-112e008efec0', 1, 102, 3, 'standard', 'Kto zginął w bitwie pod Grunwaldem jako wielki mistrz zakonu krzyżackiego?', null, 'Wielki mistrz Ulrich von Jungingen poległ w bitwie 15 lipca 1410 r.', 2, 'manual', '[{"title": "Jan Długosz, Roczniki", "url": "https://pl.wikisource.org/"}]'::jsonb, 'approved', '85642e825880b4190d631610a3ba7bab'),
  ('26a65a95-ee6c-5eef-ada6-75397c81995c', 1, 102, 3, 'standard', 'W którym roku Karol Wielki został koronowany na cesarza?', null, 'Papież Leon III koronował Karola Wielkiego w Rzymie w Boże Narodzenie 800 r.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'ed8b89c67706fdbb97105e009997cd07'),
  ('a2ce2c23-5623-5f56-98d6-7efe187599e7', 1, 102, 4, 'standard', 'Jaki dokument podpisał angielski król Jan bez Ziemi w 1215 r.?', null, 'Magna Charta Libertatum z 1215 r. ograniczała władzę króla na rzecz baronów.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '557d2c53617474f48fc8606271eda201'),
  ('6c0ab02b-5a70-5ab0-94d6-5a9024f5d07c', 1, 101, 1, 'standard', 'W którym kraju znajdują się piramidy w Gizie?', null, 'Piramidy w Gizie to jedyny zachowany do dziś cud świata starożytnego.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'f180b96229917fb4799d9892ad8afea2'),
  ('b04b1e0b-2095-5d96-81ff-148f1d852a3d', 1, 101, 2, 'standard', 'Kto był pierwszym cesarzem rzymskim?', null, 'Oktawian otrzymał tytuł Augusta w 27 r. p.n.e.; Juliusz Cezar był dyktatorem, nie cesarzem.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '4ee03711d3382ec03575dccc405662f8'),
  ('0a0aaa72-2c87-587c-a96d-d1bbea2fd4fb', 1, 101, 3, 'standard', 'W którym roku upadło Cesarstwo Zachodniorzymskie?', null, 'W 476 r. Odoaker zdetronizował Romulusa Augustulusa. Rok 1453 to upadek Konstantynopola.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'e33f93a111c8c620f233ec8cca46c551'),
  ('1c526a15-2fb0-56e8-8e35-ae525d43d24a', 1, 101, 4, 'standard', 'Która bitwa z 490 r. p.n.e. zakończyła pierwszą wyprawę perską na Grecję?', null, 'Ateńczycy pod wodzą Miltiadesa pokonali Persów pod Maratonem w 490 r. p.n.e.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'dc2916e49fb5ad469d69688534215506'),
  ('4b532249-88dc-5b19-bdb3-5d1f11cb3ee4', 1, 101, 5, 'standard', 'Jak nazywał się zbiór praw babilońskiego władcy z XVIII w. p.n.e.?', null, 'Kodeks Hammurabiego, wyryty na steli, zawiera m.in. zasadę „oko za oko”.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '27ffbbd25174332152401003580f52de'),
  ('6ab4a9c5-5cf9-5ec4-80a7-12021a5a7dcc', 1, 104, 2, 'standard', 'W którym roku Krzysztof Kolumb dotarł do Ameryki?', null, '12 października 1492 r. wyprawa Kolumba dotarła do wysp Bahama.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '668b57224a97690bd53c30c74e9c2fda'),
  ('1432d71b-0966-5179-a9e6-c650dcac90e1', 1, 104, 3, 'standard', 'Kto ogłosił 95 tez w 1517 roku, dając początek reformacji?', null, 'Marcin Luter ogłosił tezy w Wittenberdze 31 października 1517 r.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '67fd85803b7f99d77410709715f88647'),
  ('a658bd52-0eaf-551f-981a-52a0d5a0e635', 1, 104, 4, 'standard', 'Który król Polski dowodził odsieczą wiedeńską w 1683 r.?', null, '12 września 1683 r. Jan III Sobieski rozbił wojska tureckie pod Wiedniem.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '2ffb0e2a0c6b5f2a77336fcc5b1b390b'),
  ('ea2a07b2-da40-56c8-ac42-043604030c12', 1, 105, 2, 'standard', 'W którym roku Polska odzyskała niepodległość po rozbiorach?', null, '11 listopada 1918 r. Józef Piłsudski przejął władzę wojskową w Warszawie.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'fe60a6d97111872fd935f4c9055e6b14'),
  ('c10fecab-1b40-58c2-9fa7-15c23f8aad59', 1, 105, 3, 'standard', 'Kiedy wybuchło powstanie styczniowe?', null, 'Powstanie styczniowe wybuchło 22 stycznia 1863 r.; listopadowe – w 1830 r.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'dbacd4cb0ae47e057c3a8018718aea51'),
  ('00062bcb-e7f2-5aab-a258-6a7a23353961', 1, 105, 4, 'standard', 'Na jakiej wyspie zmarł Napoleon Bonaparte?', null, 'Po klęsce pod Waterloo Napoleon został zesłany na Wyspę Świętej Heleny, gdzie zmarł w 1821 r. Na Elbie przebywał wcześniej (1814–1815).', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '1d3bbdf31b553c899155a52e4f451844'),
