  ('6275700c-7cc3-5fbb-87a0-7ca8b1a38f6b', 1, 107, 3, 'standard', 'Jak nazywała się operacja lądowania aliantów w Normandii w 1944 r.?', null, 'Operacja Overlord rozpoczęła się 6 czerwca 1944 r. (D-Day). Barbarossa to atak Niemiec na ZSRR.', 3, 'manual', '[{"title": "Encyklopedia PWN – II wojna światowa", "url": "https://encyklopedia.pwn.pl/"}]'::jsonb, 'approved', 'a04562e13b1f8a12f2c1005274b22630'),
