  ('48d73444-b018-5a05-8444-bce4e066a3ee', 1, null, 3, 'detective', 'Kim jestem?', '["Urodziłem się w Toruniu.", "Studiowałem w Krakowie, Bolonii i Padwie.", "Napisałem traktat o monecie.", "Moje dzieło ukazało się w roku mojej śmierci."]'::jsonb, 'Kopernik (1473–1543) napisał też „Traktat o monecie”, a „De revolutionibus” wydano w 1543 r.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'd74e72edd0dfb242202b11b8a67e375c'),
  ('6225b559-e2fd-5bdf-941d-2106ea93729d', 1, null, 4, 'detective', 'Które to wydarzenie?', '["Rok: 1683.", "Udział wzięła husaria.", "Wojska Kara Mustafy poniosły klęskę.", "Rozegrało się u stóp Kahlenbergu."]'::jsonb, '12 września 1683 r. Jan III Sobieski rozbił armię turecką pod Wiedniem.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'afd42f839b9cf090b75684685b93086e'),
  ('32297717-cfcf-5502-8728-6790294079f6', 4, null, 3, 'detective', 'Kim jest uczona?', '["Urodziła się w Warszawie.", "Studiowała w Paryżu.", "Odkryła dwa pierwiastki.", "Jeden nazwała na cześć ojczyzny."]'::jsonb, 'Polon nazwano na cześć Polski.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'd7705a327ae32a42bdb4b520100a740b'),
  ('2b72f861-8aaf-54ae-b477-a0524ae5b4d8', 2, null, 2, 'detective', 'Jakie to miasto?', '["Leży nad Wisłą.", "Było stolicą Polski przez kilka wieków.", "Ma smoka w herbowej legendzie.", "Nad miastem góruje Wawel."]'::jsonb, 'Kraków był stolicą do przeniesienia dworu do Warszawy za Zygmunta III Wazy (1596–1611).', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'cdc6498741e43260117acb838176ec61'),
  ('38cfe117-e1e2-572a-ac34-9b1d19a20a12', 2, null, 4, 'detective', 'Jakie to państwo?', '["Leży w Ameryce Południowej.", "Nie ma dostępu do morza.", "Ma dwie stolice.", "Znajduje się tam jezioro Titicaca."]'::jsonb, 'Boliwia ma stolicę konstytucyjną Sucre i siedzibę rządu w La Paz; Paragwaj też nie ma morza, ale ma jedną stolicę.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '5077806e4947bcfee432e26a111aeeea'),
  ('3cd713c1-0fd6-5419-912b-27956102ade1', 9, null, 3, 'detective', 'Który to utwór?', '["Napisany trzynastozgłoskowcem.", "Akcja dzieje się w Soplicowie.", "Ma 12 ksiąg.", "Kończy się polonezem."]'::jsonb, 'Epopeja Mickiewicza kończy się polonezem prowadzonym przez Podkomorzego.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '62b6c48cd835134322ce00a105627298'),
  ('b7ff0196-fe45-5fd1-baac-8d23e0204dcd', 13, null, 3, 'detective', 'Kim jest bohater?', '["Był synem Zeusa i Alkmeny.", "Wykonał dwanaście prac.", "Pokonał lwa nemejskiego.", "Rzymianie nazywali go Herkulesem."]'::jsonb, 'Herakles (Herkules) – syn Zeusa i Alkmeny, słynący z dwunastu prac.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '8891e883e021a6bb9301798f9ef68c79'),
  ('c08ccc88-23c5-537f-8780-0180526031e9', 20, null, 4, 'detective', 'Kim jestem?', '["Byłem brytyjskim matematykiem.", "Pracowałem w Bletchley Park.", "Opisałem abstrakcyjną maszynę obliczeniową.", "Mój test dotyczy inteligencji maszyn."]'::jsonb, 'Alan Turing – maszyna Turinga (1936), test Turinga (1950).', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '0221e25a02a6dcc31a71702765e66c9e'),
  ('10b929d5-0d62-5457-9f3e-163e2b0d6fc9', 24, null, 3, 'detective', 'Jakie to ciało niebieskie?', '["To planeta.", "Ma najwięcej znanych księżyców spośród planet.", "Jest znana z wyraźnych pierścieni.", "Jej gęstość jest mniejsza od gęstości wody."]'::jsonb, 'Saturn ma średnią gęstość ok. 0,69 g/cm³ i najbardziej okazały system pierścieni.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'c06afa8907f93e26e9629003c0328600'),
  ('c023f9c6-7d7e-5f75-9090-0a0c05bdcb39', 14, null, 4, 'detective', 'Który to obraz?', '["Namalował go Leonardo da Vinci.", "Przedstawia kobietę ze zwierzęciem.", "Znajduje się w Polsce.", "Model to prawdopodobnie Cecylia Gallerani."]'::jsonb, '„Dama z gronostajem” jest w Muzeum Książąt Czartoryskich w Krakowie.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'c2abf97ab08e9112f60fe1c812d2a227'),
  ('f2ed7204-d000-5632-8568-2956627cbaec', 18, null, 3, 'detective', 'Kim jest sportowiec?', '["Jest polskim piłkarzem.", "Grał w Lechu Poznań i Borussii Dortmund.", "Strzelił 5 goli w 9 minut w meczu Bundesligi.", "Jest rekordzistą reprezentacji Polski w liczbie goli."]'::jsonb, '22 września 2015 r. Lewandowski strzelił 5 goli w 9 minut przeciw VfL Wolfsburg.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'd16df198fd29c7a446eccdd395bcd356'),
  ('b208b916-deb8-5b89-a66d-1683877902f8', 15, null, 3, 'detective', 'Kim jest kompozytor?', '["Urodził się w XIX wieku na Mazowszu.", "Pisał głównie na fortepian.", "Zmarł w Paryżu.", "Jego serce wróciło do Warszawy."]'::jsonb, 'Chopin urodził się w Żelazowej Woli (1810), zmarł w Paryżu (1849).', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '938e2080fdf0bca9eec5ef6940cae709'),
  ('04ee5785-5d89-5e7c-ae3a-830c5f324378', 8, null, 5, 'detective', 'Jaki to pierwiastek?', '["Jest gazem szlachetnym.", "Jest drugim najlżejszym pierwiastkiem.", "Odkryto go najpierw w widmie Słońca.", "Używa się go do napełniania balonów."]'::jsonb, 'Hel wykryto w 1868 r. w widmie słonecznym; nazwa od greckiego helios – Słońce.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'ed50c0a77062d84ce80906fc7f705ae9'),
  ('18b56d53-c282-5717-9400-73070bc6f3c8', 27, null, 4, 'detective', 'Kim jestem?', '["Byłem szkockim bakteriologiem.", "Pracowałem w Londynie.", "Pewna pleśń zniszczyła moje kultury bakterii.", "Otrzymałem Nobla w 1945 r."]'::jsonb, 'Fleming zauważył działanie pleśni Penicillium w 1928 r.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', 'cd4dd812ad549aa73c156440625e27f2'),
  ('7db7c6e7-5705-5257-9d91-eda00c737038', 10, null, 5, 'detective', 'Kim jest filozof?', '["Pochodził z Królewca.", "Podobno nigdy nie wyjechał daleko od rodzinnego miasta.", "Mieszkańcy regulowali zegarki według jego spacerów.", "Sformułował imperatyw kategoryczny."]'::jsonb, 'Kant (1724–1804) całe życie spędził w Królewcu i okolicach.', null, 'manual', '[{"title": "Redakcja QuizVerse – pytanie zweryfikowane ręcznie", "url": null}]'::jsonb, 'approved', '63e5464e1d679b091ea9af6971e9a082')
